// Advisor logic shared by the API route and the advisor page.
// Estimates come from lib/advisorData.ts, generated by scripts/build_profile_backtests.py
// (walk-forward replay of the saved GAT + PPO models, 2019 to 2025, net of 10 bps cost).
import { ADVISOR } from './advisorData';

export type ProfileKey = 'conservative' | 'moderate' | 'aggressive';
export type Sector = 'All' | 'Financial' | 'Oil & Gas' | 'Consumer' | 'ICT';
export type Holding = { ticker: string; sector: string; weight: number; gat_rank: number; in_focus: boolean };

export type Recommendation = {
  signal_date: string;
  model_year: number;
  stale_days: number;
  universe: number;
  eligible_assets: number;
  sector: Sector;
  rebalance: string;
  max_weight: number;
  portfolios: Record<ProfileKey, Holding[]>;
};
export type RecommendationResponse = Recommendation & {
  source: 'live' | 'snapshot';
  notice?: string;
};

export const PROFILE_KEYS: ProfileKey[] = ['conservative', 'moderate', 'aggressive'];
export const SECTORS: Sector[] = ['All', 'Financial', 'Oil & Gas', 'Consumer', 'ICT'];

/* ── Investment parameter limits ─────────────────────────────────────────────
   Amount: the floor keeps every position at least one share for most picks at
   indicative prices; the ceiling reflects concentrated NGX liquidity (RQ4).
   Duration: the model rebalances monthly, so one month is the shortest horizon it
   can act on; 12 months matches one annual walk-forward fold, the unit in which
   the thesis reports performance. Beyond 68 months there is no full historical
   window to estimate from.                                                    */
export const AMOUNT_MIN = 50_000;
export const AMOUNT_MAX = 10_000_000;
export const AMOUNT_PRESETS = [50_000, 100_000, 500_000, 1_000_000, 5_000_000, 10_000_000];
export const HORIZON_MIN_MONTHS = 1;
export const HORIZON_SUGGESTED_MONTHS = 12;
export const HORIZON_MAX_MONTHS = 120;
export const HISTORY_MONTHS = ADVISOR.months.length;

