export function profileFromScore(score: number): ProfileKey {
  if (score <= 8) return 'conservative';
  if (score <= 12) return 'moderate';
  return 'aggressive';
}

/** Short horizons step the suggestion down one level: less time to recover from a drawdown. */
export function recommendedProfile(score: number, horizonMonths: number): { key: ProfileKey; adjusted: boolean } {
  const base = profileFromScore(score);
  if (horizonMonths >= HORIZON_SUGGESTED_MONTHS || base === 'conservative') return { key: base, adjusted: false };
  return { key: base === 'aggressive' ? 'moderate' : 'conservative', adjusted: true };
}

/* ── Historical estimates ───────────────────────────────────────────────── */
type MetricKey = keyof typeof ADVISOR.metrics;
export type Metrics = (typeof ADVISOR.metrics)[MetricKey];

export function metricsFor(sector: Sector, profile: ProfileKey): Metrics {
  return ADVISOR.metrics[`${sector}|${profile}` as MetricKey];
}

export function seriesFor(sector: Sector, profile: ProfileKey): number[] {
  return ADVISOR.monthly[`${sector}|${profile}` as keyof typeof ADVISOR.monthly];
}

const quantile = (sorted: number[], q: number) => {
  const pos = (sorted.length - 1) * q;
  const lo = Math.floor(pos), hi = Math.ceil(pos);
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
};

/** Compounded returns over every rolling window of `months` in the 68-month walk-forward history. */
export function horizonStats(series: number[], months: number) {
  if (months > series.length) return null;
  const outcomes: number[] = [];
  for (let i = 0; i + months <= series.length; i++) {
    outcomes.push(series.slice(i, i + months).reduce((w, r) => w * (1 + r), 1) - 1);
  }
  const sorted = [...outcomes].sort((a, b) => a - b);
  return {
    windows: outcomes.length,
    positiveShare: outcomes.filter(r => r > 0).length / outcomes.length,
    p25: quantile(sorted, 0.25),
    p50: quantile(sorted, 0.5),
    p75: quantile(sorted, 0.75),
    worst: sorted[0],
  };
}

/** Smallest amount that buys at least one share of every holding at indicative prices. */
export function minimumToHoldAll(holdings: Holding[]): number {
  return Math.max(...holdings.map(h => (ADVISOR.prices[h.ticker as keyof typeof ADVISOR.prices] ?? 0) / h.weight));
}

export const priceOf = (ticker: string): number | undefined => ADVISOR.prices[ticker as keyof typeof ADVISOR.prices];
export const nameOf = (ticker: string): string => ADVISOR.names[ticker as keyof typeof ADVISOR.names] ?? ticker;

export function formatNGN(v: number, compact = false) {
  if (compact && v >= 1_000_000) return `₦${(v / 1_000_000).toFixed(v % 1_000_000 === 0 ? 0 : 2)}M`;
  if (compact && v >= 1_000) return `₦${(v / 1_000).toFixed(0)}K`;
  return `₦${Math.round(v).toLocaleString('en-NG')}`;
}

export const pct = (v: number, d = 1) => `${v > 0 ? '+' : ''}${(v * 100).toFixed(d)}%`;

export function formatHorizon(months: number) {
  if (months % 12 === 0) return `${months / 12} year${months === 12 ? '' : 's'}`;
  if (months > 12) return `${Math.floor(months / 12)} yr ${months % 12} mo`;
  return `${months} month${months === 1 ? '' : 's'}`;
}
